SELECT

FROM wms_shipment_order so
LEFT JOIN wms_warehouse w ON so.warehouse_id = w.id

    AND so.shipment_type = #{shipmentType}
    AND so.order_status = #{orderStatus}
    AND so.warehouse_id = #{warehouseId}
    AND so.customer_name LIKE CONCAT('%', #{customerName}, '%')
    AND so.create_time >= #{startTime}
    AND so.create_time <= #{endTime}

ORDER BY so.create_time DESC
LIMIT #{query.pageNum}, #{query.pageSize}

